package com.radha.music;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.Toast;
import androidx.core.content.FileProvider;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** Explicit update downloads from public GitHub Releases; Android approves installation. */
final class AppUpdates {
 private final Activity activity;private final SharedPreferences prefs;private final DownloadManager downloads;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 private boolean closed,checking,verifying,resumed;private String offered="";
 AppUpdates(Activity activity){this.activity=activity;prefs=activity.getSharedPreferences("app_updates",0);downloads=activity.getSystemService(DownloadManager.class);}
 private String version()throws PackageManager.NameNotFoundException{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;}
 void check(boolean manual){if(closed||checking)return;if(prefs.getLong("download",-1)!=-1){resume();if(manual)toast("Checking your update download…");return;}checking=true;if(manual)toast("Checking for updates…");worker.execute(()->{UpdateRules.Release release=null;Exception failure=null;try{HttpURLConnection connection=(HttpURLConnection)new URL("https://api.github.com/repos/"+UpdateRules.REPO+"/releases/latest").openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(10000);connection.setRequestProperty("Accept","application/vnd.github+json");connection.setRequestProperty("User-Agent","Radha-Music-Updater");try{int status=connection.getResponseCode();if(status!=404){if(status!=200)throw new IOException("GitHub response "+status);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>1024*1024)throw new IOException("Release response too large");out.write(bytes,0,n);}release=UpdateRules.parse(out.toString("UTF-8"),version());}}}finally{connection.disconnect();}}catch(Exception e){failure=e;}UpdateRules.Release found=release;Exception error=failure;main.post(()->{checking=false;if(closed||!resumed||activity.isFinishing())return;if(found!=null&&(manual||!offered.equals(found.version()))){offered=found.version();new AlertDialog.Builder(activity).setTitle("Radha Music "+found.version()+" is ready").setMessage("Download the update from Diwash Bhatta’s GitHub release? Your music and settings will stay on this device. Android will ask you to confirm installation.").setPositiveButton("Download update",(d,w)->download(found)).setNegativeButton("Later",null).show();}else if(manual)toast(error==null?"You have the latest available version":"Could not check updates. Try again later.");});});}
 private File file(){File root=activity.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);if(root==null)throw new IllegalStateException("Download storage unavailable");File dir=new File(root,"updates");dir.mkdirs();return new File(dir,"Radha-Music.apk");}
 private void download(UpdateRules.Release release){try{File target=file();if(target.exists()&&!target.delete())throw new IOException("Could not replace old update");DownloadManager.Request request=new DownloadManager.Request(Uri.parse(release.url())).setTitle("Radha Music update").setDescription(release.version()).setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationUri(Uri.fromFile(target));long id=downloads.enqueue(request);prefs.edit().putLong("download",id).putString("sha256",release.sha256()).putLong("size",release.size()).putString("version",release.version()).apply();toast("Update downloading. You can keep using Radha Music.");resume();}catch(Exception e){toast("Could not start the update download.");}}
 void resume(){resumed=true;main.removeCallbacks(poll);main.post(poll);}
 void pause(){resumed=false;main.removeCallbacks(poll);}
 private final Runnable poll=new Runnable(){public void run(){if(closed||!resumed)return;long id=prefs.getLong("download",-1);if(id<0||verifying)return;try(Cursor cursor=downloads.query(new DownloadManager.Query().setFilterById(id))){if(cursor==null||!cursor.moveToFirst()){prefs.edit().remove("download").apply();return;}int status=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_SUCCESSFUL){verify();return;}if(status==DownloadManager.STATUS_FAILED){downloads.remove(id);prefs.edit().remove("download").apply();toast("Update download failed. Use Settings → Check for updates to retry.");return;}}catch(Exception e){toast("Could not read update download status.");return;}main.postDelayed(this,1500);}};
 private void verify(){verifying=true;worker.execute(()->{Exception failure=null;boolean newer=false;try{File apk=file();if(apk.length()!=prefs.getLong("size",-1))throw new IOException("Incomplete update");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(apk)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1)digest.update(bytes,0,n);}StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(Locale.US,"%02x",b&255));if(!hex.toString().equalsIgnoreCase(prefs.getString("sha256","")))throw new IOException("Update checksum did not match");PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo downloaded=pm.getPackageArchiveInfo(apk.getPath(),flags),installed=pm.getPackageInfo(activity.getPackageName(),flags);if(downloaded==null||!activity.getPackageName().equals(downloaded.packageName)||signatures(downloaded)==null||signatures(downloaded).length==0||!Arrays.equals(signatures(downloaded),signatures(installed)))throw new IOException("Update signer did not match");newer=Build.VERSION.SDK_INT>=28?downloaded.getLongVersionCode()>installed.getLongVersionCode():downloaded.versionCode>installed.versionCode;}catch(Exception e){failure=e;}Exception error=failure;boolean install=newer;main.post(()->{verifying=false;if(closed)return;if(error!=null){long id=prefs.getLong("download",-1);if(id>=0)downloads.remove(id);prefs.edit().remove("download").apply();toast("Update verification failed. Download again from Settings.");return;}if(!install){long id=prefs.getLong("download",-1);if(id>=0)downloads.remove(id);prefs.edit().clear().apply();return;}if(resumed)new AlertDialog.Builder(activity).setTitle("Update ready").setMessage("Install the downloaded Radha Music update?").setPositiveButton("Install",(d,w)->install()).setNegativeButton("Later",null).show();});});}
 private static Signature[] signatures(PackageInfo info){return Build.VERSION.SDK_INT>=28&&info.signingInfo!=null?info.signingInfo.getApkContentsSigners():info.signatures;}
 private void install(){try{if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Allow Radha Music updates").setMessage("Enable “Allow from this source” on the next Android screen, then return here to install.").setPositiveButton("Open settings",(d,w)->activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())))).setNegativeButton("Cancel",null).show();return;}Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".updates",file());Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}catch(Exception e){toast("Android could not open the installer. Try again from Settings.");}}
 private void toast(String text){if(!closed)Toast.makeText(activity,text,Toast.LENGTH_LONG).show();}
 void close(){closed=true;main.removeCallbacksAndMessages(null);worker.shutdownNow();}
}
